package glitch

import data.glitch_lib

# Weak encryption algorithms and patterns
weak_algorithms := {"DES", "3DES", "RC2", "RC4", "MD5", "SHA1", "SHA-1", "ECB"}

weak_tls_versions := {"1.0", "1.1", "SSLv3", "SSLv2", "TLS1.0", "TLS1.1", "TLSv1.0", "TLSv1.1"}

weak_ssh_versions := {"1", "1.5", "SSH-1", "SSH1"}

# Key size thresholds below which encryption is considered weak
weak_key_sizes := {56, 64, 40, 128, 1024, 160}

# Pattern matching for weak protocol/algorithm strings
weak_algorithm_pattern := "(?i)(DES|3DES|RC2|RC4|MD5|SHA1|SHA-1|ECB|export|legacy|deprecated)"

weak_tls_pattern := "(?i)(TLS[-_]?1[-_]?[01]|SSLv[23]|TLS[-_]?v[-_]?1[-_]?[01])"

weak_ssh_pattern := "(?i)(SSH[-_]?1([-_]?5)?)"

# Helper to check if value contains weak algorithm reference
contains_weak_algorithm(value) {
    value.ir_type == "String"
    regex.match(weak_algorithm_pattern, value.value)
}

# Helper to check if value is a weak key size
is_weak_key_size(value) {
    value.ir_type == "Integer"
    weak_key_sizes[value.value]
}

is_weak_key_size(value) {
    value.ir_type == "String"
    num := to_number(value.value)
    weak_key_sizes[num]
} else = false

# Helper to check for weak protocol versions
contains_weak_protocol(value) {
    value.ir_type == "String"
    regex.match(weak_tls_pattern, value.value)
}

contains_weak_protocol(value) {
    value.ir_type == "String"
    regex.match(weak_ssh_pattern, value.value)
}

# Generic encryption-related attribute names
encryption_attrs := {"encryption", "algorithm", "cipher", "tls_version", "ssl_version", "protocol", "key_size", "key_length", "bit_length", "salt_length", "hash", "signature_algorithm", "mac_algorithm", "hmac"}

# Check attributes recursively including nested structures
check_encryption_weakness(attr) {
    attr.ir_type == "String"
    contains_weak_algorithm(attr)
}

check_encryption_weakness(attr) {
    attr.ir_type == "String"
    contains_weak_protocol(attr)
}

check_encryption_weakness(attr) {
    attr.ir_type == "Integer"
    is_weak_key_size(attr)
}

check_encryption_weakness(attr) {
    attr.ir_type == "Array"
    item := attr.value[_]
    check_encryption_weakness(item)
}

check_encryption_weakness(attr) {
    attr.ir_type == "Hash"
    val := attr.value[_]
    check_encryption_weakness(val)
}

# Check if attribute name suggests encryption context
is_encryption_related(name) {
    lower_name := lower(name)
    encryption_attrs[lower_name]
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "encrypt")
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "cipher")
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "ssl")
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "tls")
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "hash")
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "key")
}

is_encryption_related(name) {
    lower_name := lower(name)
    contains(lower_name, "algorithm")
}

# Check specific algorithm assignments in values
check_value_weakness(value) {
    value.ir_type == "String"
    algorithm := weak_algorithms[_]
    lower(value.value) == lower(algorithm)
}

# Main detection: weak encryption in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Encryption-related attribute with weak value
    is_encryption_related(attr.name)
    check_encryption_weakness(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak encryption algorithms, protocols, or insufficient key sizes. (CWE-326)"
    }
}

# Detection: explicit weak algorithm assignment in any value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_value_weakness(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak encryption algorithms, protocols, or insufficient key sizes. (CWE-326)"
    }
}

# Detection: weak key sizes in numeric attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_encryption_related(attr.name)
    is_weak_key_size(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak encryption algorithms, protocols, or insufficient key sizes. (CWE-326)"
    }
}

# Detection: weak protocols in atomic unit names/types
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
